"""Keep docs/COUNTRY_RULES.md in step with the researched rules.

Run without arguments to check (as CI does) and with --write to regenerate the file.
"""
import importlib
import sys
import types
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
COMPONENT = ROOT / "custom_components" / "car_tires_season"
DOC = ROOT / "docs" / "COUNTRY_RULES.md"
PACKAGE = "car_tires_season_docs"

OBLIGATION_TEXT = {
    "none": "No legal duty",
    "conditions": "In winter road conditions",
    "season_conditions": "In winter conditions, within the period",
    "season": "Mandatory within the period",
    "regional_season": "Within the period, on signposted roads or in zones",
}
MONTHS = "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split()


def load(name):
    if PACKAGE not in sys.modules:
        stub = types.ModuleType(PACKAGE)
        stub.__path__ = [str(COMPONENT)]
        sys.modules[PACKAGE] = stub
    return importlib.import_module(f"{PACKAGE}.{name}")


def describe_anchor(anchor):
    if anchor.easter_offset is not None:
        offset = anchor.easter_offset
        return "Easter" if offset == 0 else f"Easter {offset:+d} d"
    return f"{anchor.day} {MONTHS[anchor.month - 1]}"


def describe_rule(rule, names):
    window = f"{describe_anchor(rule.window.start)} – {describe_anchor(rule.window.end)}"
    label = OBLIGATION_TEXT[rule.obligation.value]
    kind = "legal period" if rule.has_legal_period else "practical season"
    sources = ", ".join(f"[{index}]({url})" for index, url in enumerate(rule.sources, 1))
    return f"| {names[rule.country]} (`{rule.country}`) | {label} | {window} ({kind}) | {rule.confidence} | {sources} |"


def render():
    rules_data, names = load("rules_data"), load("country_names").COUNTRY_NAMES
    languages = load("languages").LANGUAGE_COUNTRIES
    lines = [
        "# Country rules",
        "",
        "<!-- Generated by .github/checks/country_rules_doc.py --write; do not edit by hand. -->",
        "",
        "What each supported country demands of winter tires on passenger cars, and the sources",
        f"checked on {rules_data.CHECKED}. Laws change: treat this as a starting point and check the",
        "official rules before you rely on it.",
        "",
        "- **Obligation** is the type of duty. *In winter road conditions* means the duty applies whenever",
        "  snow, ice or slush occur, in any month.",
        "- **Period** is the legal period if the duty has one, otherwise the practical winter season the",
        "  integration uses when it has no weather data (this is a recommendation, not law).",
        "- **Confidence**: `high` = several current sources agree, `medium` = few sources or small",
        "  differences, `low` = only weak sources were found. A country that is not listed uses the",
        "  generic season (1 Nov – 31 Mar, or 1 Jun – 30 Sep south of the equator) and relies on the weather.",
        "",
        "| Country | Obligation | Period | Confidence | Sources |",
        "| --- | --- | --- | --- | --- |",
    ]
    for code in sorted(rules_data.RULES, key=lambda c: names[c]):
        rule = rules_data.RULES[code]
        lines.append(describe_rule(rule, names))
        for region, variant in sorted(rule.regions.items()):
            lines.append(describe_rule(variant, {variant.country: f"↳ {names[code]}, region {region}"}))
    lines += [
        "",
        "## Translations and the countries that back them",
        "",
        "Each translation ships only because the rules of the countries below were checked.",
        "",
        "| Language | Checked countries |",
        "| --- | --- |",
    ]
    for language, countries in sorted(languages.items()):
        lines.append(f"| `{language}` | {', '.join(names[c] for c in countries)} |")
    return "\n".join(lines) + "\n"


def main(arguments):
    text = render()
    if "--write" in arguments:
        DOC.parent.mkdir(exist_ok=True)
        DOC.write_text(text, encoding="utf-8")
        print(f"Wrote {DOC.relative_to(ROOT)}")
        return 0
    if not DOC.is_file() or DOC.read_text(encoding="utf-8") != text:
        print("docs/COUNTRY_RULES.md is outdated: run python .github/checks/country_rules_doc.py --write")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
